    /**
     * Method to retrieve the Position via an PositionPrimaryKey.
     * @param 	id Long
     * @return 	Position
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Position handle( FindPositionQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPositionId() );
    }
    
    /**
     * Method to retrieve a collection of all Positions
     *
     * @param	query	FindAllPositionQuery 
     * @return 	List<Position> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Position> handle( FindAllPositionQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPosition,
 * but only if the id matches
 *
 * @param		entity	Position
 */
	protected void emitFindPosition( Position entity ) {
		LOGGER.info("handling emitFindPosition" );
		
	    queryUpdateEmitter.emit(FindPositionQuery.class,
	                            query -> query.getFilter().getPositionId().equals(entity.getPositionId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPosition
	 * 
	 * @param		entity	Position
	 */
	protected void emitFindAllPosition( Position entity ) {
		LOGGER.info("handling emitFindAllPosition" );
		
	    queryUpdateEmitter.emit(FindAllPositionQuery.class,
	                            query -> true,
	                            entity);
	}

